		long leaf = diskBudgetBytes / 4L;
		long joins = diskBudgetBytes / 4L;
		long adaptive = diskBudgetBytes * 5L / 16L;
		long delta = diskBudgetBytes - exact - leaf - joins - adaptive;
		int designLanes = 4;
		int auditLanes = 2;
		int omniDepth = 3;
