		int countMinWidth = boundedPowerOfTwo(countMinWidthBudget, 256, MAXIMUM_COUNT_MIN_WIDTH);
		long sortMemory = Math.min(64L * 1024L * 1024L,
				Math.max(1024L * 1024L, diskBudgetBytes / 64L));
		long heavyCapacityFromExactTier = exact / CONSERVATIVE_HEAVY_PREDICATE_BYTES;
		int heavyCapacity = Math.toIntExact(Math.max(16L, Math.min(8192L,
				Math.max(omniWidth / 2L, heavyCapacityFromExactTier))));
