	public static FrontierStatisticsBuildConfig forBudgets(long diskBudgetBytes, long heapBudgetBytes) {
		FrontierStatisticsBuildConfig selected = forDiskBudget(diskBudgetBytes);
		FrontierStatisticsHeapGovernor governor = FrontierStatisticsHeapGovernor.forBudget(heapBudgetBytes);
		long mappedMetadataAllowance = Math.min(MAXIMUM_MAPPED_METADATA_BYTES, heapBudgetBytes / 3L);
		long builderLimit = governor.maximumNonQueryBytes() - mappedMetadataAllowance;
		if (builderLimit <= 0L) {
			throw new IllegalArgumentException("Frontier heap budget cannot retain mapped metadata and a builder");
		}

		while (FrontierStatisticsBuilder.estimatedHeapBytes(selected) > builderLimit
				&& selected.sortMemoryBytes() > MINIMUM_SORT_MEMORY_BYTES) {
			selected = withBuildDimensions(selected,
					Math.max(MINIMUM_SORT_MEMORY_BYTES, selected.sortMemoryBytes() / 2L),
					selected.countMinWidth(), selected.heavyPredicateCapacity(), selected.cellCount(),
					selected.hllPrecision(), selected.witnessCeilingPerCell());
		}
		while (FrontierStatisticsBuilder.estimatedHeapBytes(selected) > builderLimit
				&& selected.countMinWidth() > MINIMUM_COUNT_MIN_WIDTH) {
			selected = withBuildDimensions(selected, selected.sortMemoryBytes(),
					Math.max(MINIMUM_COUNT_MIN_WIDTH, selected.countMinWidth() / 2),
					selected.heavyPredicateCapacity(), selected.cellCount(), selected.hllPrecision(),
					selected.witnessCeilingPerCell());
		}
		while (FrontierStatisticsBuilder.estimatedHeapBytes(selected) > builderLimit
				&& selected.heavyPredicateCapacity() > 16) {
			selected = withBuildDimensions(selected, selected.sortMemoryBytes(), selected.countMinWidth(),
					Math.max(16, selected.heavyPredicateCapacity() / 2), selected.cellCount(),
					selected.hllPrecision(), selected.witnessCeilingPerCell());
		}
		while (FrontierStatisticsBuilder.estimatedHeapBytes(selected) > builderLimit
				&& selected.hllPrecision() > 4) {
			selected = withBuildDimensions(selected, selected.sortMemoryBytes(), selected.countMinWidth(),
					selected.heavyPredicateCapacity(), selected.cellCount(), selected.hllPrecision() - 1,
					selected.witnessCeilingPerCell());
		}
		while (FrontierStatisticsBuilder.estimatedHeapBytes(selected) > builderLimit
				&& selected.witnessCeilingPerCell() > selected.witnessFloorPerCell()) {
			selected = withBuildDimensions(selected, selected.sortMemoryBytes(), selected.countMinWidth(),
					selected.heavyPredicateCapacity(), selected.cellCount(), selected.hllPrecision(),
					Math.max(selected.witnessFloorPerCell(), selected.witnessCeilingPerCell() / 2));
		}
		while (FrontierStatisticsBuilder.estimatedHeapBytes(selected) > builderLimit
				&& selected.cellCount() > 2) {
			selected = withBuildDimensions(selected, selected.sortMemoryBytes(), selected.countMinWidth(),
					selected.heavyPredicateCapacity(), selected.cellCount() / 2, selected.hllPrecision(),
					selected.witnessCeilingPerCell());
		}
		long estimatedHeap = FrontierStatisticsBuilder.estimatedHeapBytes(selected);
		if (estimatedHeap > builderLimit) {
			throw new IllegalArgumentException("Frontier heap budget cannot admit the minimum bounded build profile");
		}
		return selected;
	}

